    os.chdir(os.path.dirname(os.path.abspath(__file__)))
    out, bad = {}, []
    for ch, t, q, a, y in ITEMS:
        for field in (q, a):
            if re.search(r'[$\\]|\\text|leftarrow', field): bad.append(('latex', q))
        if not (q.strip() and a.strip()): bad.append(('empty', q))
        out.setdefault(ch, []).append({'t': t, 'q': q, 'a': a, 'y': [y], 'n': 1})
    if bad: print('BAD', bad); sys.exit(1)
    json.dump(out, open('qbank/wiz3.json', 'w', encoding='utf8'), ensure_ascii=False)
    print('wiz3:', len(ITEMS), 'cards;', {k: len(v) for k, v in sorted(out.items())})
